6	using namespace llm_npc;
7	
8	namespace {
9	
10	// A client pointed at a port nothing listens on — combat tests never make
11	// LLM requests.
12	LlmClient& idleClient() {
13	    static LlmClient client(LlmConfig{/*host=*/"127.0.0.1", /*port=*/1});
14	    return client;
15	}
16	
17	Npc makeCivilian() {
18	    Persona p;
19	    p.name = "Gus";
20	    p.role = "hot-dog vendor";
21	    p.armed = false;
22	    Npc npc(p, idleClient());
23	    npc.setPlacement({0.f, 0.f, 0.f}, 0.f, "cart");
24	    return npc;
25	}
26	
27	Npc makeCop() {
28	    Persona p;
29	    p.name = "Officer Dana Brooks";
30	    p.role = "beat cop";
31	    p.armed = true;
32	    Npc npc(p, idleClient());
33	    npc.setPlacement({0.f, 0.f, -36.f}, 0.f, "police");
34	    return npc;
35	}
36	
37	}  // namespace
38	
39	// ---- NpcState transitions -----------------------------------------------
40	
41	TEST_CASE("Civilian transitions to Fleeing when hit") {
42	    auto npc = makeCivilian();
43	    CHECK(npc.combatState() == NpcState::Idle);
44	    npc.takeDamage(10);
45	    CHECK(npc.combatState() == NpcState::Fleeing);
46	    CHECK(npc.hp() == 90);
47	}
48	
49	TEST_CASE("Cop transitions to Hostile when hit") {
50	    auto npc = makeCop();
51	    CHECK(npc.combatState() == NpcState::Idle);
52	    npc.takeDamage(10);
53	    CHECK(npc.combatState() == NpcState::Hostile);
54	    CHECK(npc.hp() == 90);
55	}
56	
57	TEST_CASE("NPC transitions to Dead when HP reaches 0") {
58	    auto npc = makeCivilian();
59	    npc.takeDamage(100);
60	    CHECK(npc.combatState() == NpcState::Dead);
61	    CHECK(npc.hp() == 0);
62	}
63	
64	TEST_CASE("takeDamage is no-op on Dead NPC") {
65	    auto npc = makeCivilian();
66	    npc.takeDamage(100);  // kills
67	    REQUIRE(npc.combatState() == NpcState::Dead);
68	    npc.takeDamage(50);   // should be ignored
69	    CHECK(npc.hp() == 0);
70	    CHECK(npc.combatState() == NpcState::Dead);
71	}
72	
73	TEST_CASE("NPC HP does not go negative") {
74	    auto npc = makeCivilian();
75	    npc.takeDamage(200);
76	    CHECK(npc.hp() == 0);
77	}
78	
79	TEST_CASE("Multiple partial hits accumulate correctly") {
80	    auto npc = makeCivilian();
81	    npc.takeDamage(30);
82	    CHECK(npc.hp() == 70);
83	    npc.takeDamage(30);
84	    CHECK(npc.hp() == 40);
85	    CHECK(npc.combatState() == NpcState::Fleeing);
86	}
87	
88	TEST_CASE("Armed NPC stays Hostile after multiple hits") {
89	    auto npc = makeCop();
90	    npc.takeDamage(20);
91	    CHECK(npc.combatState() == NpcState::Hostile);
92	    npc.takeDamage(20);
93	    CHECK(npc.combatState() == NpcState::Hostile);
94	    CHECK(npc.hp() == 60);
95	}
96	
97	TEST_CASE("isArmed matches persona armed flag") {
