75	// Unit forward vector on the ground plane for a yaw in degrees.
76	Vec3 flatForward(float yawDeg) {
77	    return normalize(Vec3{std::sin(degToRad(yawDeg)), 0.f, std::cos(degToRad(yawDeg))});
78	}
79	
80	// Ground-plane right vector for a yaw in degrees.
81	Vec3 flatRight(float yawDeg) {
82	    const Vec3 f = flatForward(yawDeg);
83	    return Vec3{f.z, 0.f, -f.x};
84	}
85	
86	#ifdef __APPLE__
87	// On macOS, SFML re-centers the cursor by posting a synthetic mouse event
88	// whose coordinates land in the wrong place (and which the OS may drop
89	// entirely without Accessibility permission), so the camera saw a large
90	// constant delta every frame and spun. Bypass SFML: read the true cursor
91	// location and warp it back to a fixed anchor, all in CoreGraphics global
92	// coordinates so the loop is self-consistent.
93	CGPoint gMouseAnchor{-1.0, -1.0};
94	
95	CGPoint currentCursorLocation() {
96	    CGEventRef ev = CGEventCreate(nullptr);
97	    const CGPoint p = CGEventGetLocation(ev);
98	    CFRelease(ev);
99	    return p;
100	}
101	
102	// "Re-centering" on macOS means re-anchoring at the cursor's current spot;
103	// the anchor only needs to be a fixed reference point for deltas.
104	void centerMouse(sf::RenderWindow&) {
105	    gMouseAnchor = currentCursorLocation();
106	}
107	
108	// Applies one frame of mouse look to the camera and warps the cursor back
109	// to the anchor so deltas keep accumulating.
110	void handleMouseLook(sf::RenderWindow& window, CameraPose& camera) {
111	    if (!window.hasFocus()) return;
112	    if (gMouseAnchor.x < 0.0) {
113	        gMouseAnchor = currentCursorLocation();
114	        return;
115	    }
116	    const CGPoint cur = currentCursorLocation();
117	    const float dx = static_cast<float>(cur.x - gMouseAnchor.x);
118	    const float dy = static_cast<float>(cur.y - gMouseAnchor.y);
119	    camera.yawDeg += dx * kMouseSensitivity;
120	    camera.pitchDeg = clampf(camera.pitchDeg - dy * kMouseSensitivity,
121	                             -kMaxPitchDeg, kMaxPitchDeg);
122	    CGWarpMouseCursorPosition(gMouseAnchor);
123	    // The warp suspends mouse events briefly by default; re-associating
124	    // cancels that so look stays smooth.
125	    CGAssociateMouseAndMouseCursorPosition(true);
126	}
127	#else
128	// Re-centers the OS cursor so relative mouse-look deltas keep working.
129	void centerMouse(sf::RenderWindow& window) {
130	    sf::Mouse::setPosition(sf::Vector2i(static_cast<int>(window.getSize().x / 2),
131	                                        static_cast<int>(window.getSize().y / 2)),
132	                           window);
133	}
134	
135	// Applies one frame of mouse look to the camera and re-centers the cursor.
136	void handleMouseLook(sf::RenderWindow& window, CameraPose& camera) {
137	    const sf::Vector2i center(static_cast<int>(window.getSize().x / 2),
138	                              static_cast<int>(window.getSize().y / 2));
139	    const sf::Vector2i delta = sf::Mouse::getPosition(window) - center;
140	    camera.yawDeg += static_cast<float>(delta.x) * kMouseSensitivity;
141	    camera.pitchDeg = clampf(camera.pitchDeg - static_cast<float>(delta.y) * kMouseSensitivity,
142	                             -kMaxPitchDeg, kMaxPitchDeg);
143	    if (window.hasFocus()) centerMouse(window);
144	}
